define([],function(){function uuid(){if(window.crypto&&window.crypto.randomUUID){return window.crypto.randomUUID().replace(/-/g,'');}if(window.crypto&&window.crypto.getRandomValues){var bytes=new Uint8Array(16);window.crypto.getRandomValues(bytes);return Array.prototype.map.call(bytes,function(byte){return('0'+byte.toString(16)).slice(-2);}).join('');}uuid.counter=(uuid.counter||0)+1;var perf=window.performance&&typeof window.performance.now==='function'?Math.floor(window.performance.now()*1000).toString(36):'0';var identifier=Date.now().toString(36)+perf+uuid.counter.toString(36);while(identifier.length<16){identifier+=Date.now().toString(36)+uuid.counter.toString(36);}return('sess'+identifier).substring(0,52);}return{uuid:uuid};});
